/* Signature Esperanto Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Espera": "From espero (hope): 'hope'.", "Amiko": "From amiko (friend).", "Lumo": "From lumo (light).", "Koro": "From koro (heart).", "Stelo": "From stelo (star).", "Paco": "From paco (peace).", "Esperano": "Signature surname: 'of hope'.", "Lumano": "Signature surname: 'of light'.", "Stelano": "Signature surname: 'of the star'.", "Pacano": "Signature surname: 'of peace'."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Espera';
console.log(lookup(q));

